// Extruded Sprite 3D - shared runtime.
// Installed once per game by onFirstSceneLoaded (and defensively by onCreated).
// Everything below is idempotent: re-running it is a no-op.
if (typeof THREE === 'undefined') {
    return;
}

if (!gdjs.__extrudedSprite3D) {
  const maskCache = new Map();
  const geometryCache = new Map();
  const materialCache = new Map();
  const depthMaterialCache = new Map();
  const liveRenderers = new Set();
  const warnedOnce = new Set();
  const MASK_CACHE_LIMIT = 32;
  const GEOMETRY_CACHE_LIMIT = 64;
  const MATERIAL_CACHE_LIMIT = 128;
  const warnOnce = (key, message) => {
    if (warnedOnce.has(key)) {
      return;
    }
    warnedOnce.add(key);
    console.warn("[ExtrudedSprite3D] " + message);
  };
  // Caches are shared between every instance, so an entry can only be thrown
  // away when no live renderer is still drawing with it.
  const collectGeometriesInUse = () => {
    const inUse = new Set();
    liveRenderers.forEach((renderer) => {
      if (renderer.currentGeometryKey) {
        inUse.add(renderer.currentGeometryKey);
      }
    });
    return inUse;
  };
  const collectMaterialsInUse = () => {
    const inUse = new Set();
    liveRenderers.forEach((renderer) => {
      const meshes = [renderer.frontBackMesh, renderer.sideMesh, renderer.frontBackWireMesh, renderer.sideWireMesh];
      for (const mesh of meshes) {
        if (!mesh) {
          continue;
        }
        if (mesh.material) {
          inUse.add(mesh.material.uuid);
        }
        if (mesh.customDepthMaterial) {
          inUse.add(mesh.customDepthMaterial.uuid);
        }
        if (mesh.customDistanceMaterial) {
          inUse.add(mesh.customDistanceMaterial.uuid);
        }
      }
