    return inUse;
  };
  const trimGeometryCache = () => {
    if (geometryCache.size <= GEOMETRY_CACHE_LIMIT) {
      return;
    }
    const inUse = collectGeometriesInUse();
    for (const key of Array.from(geometryCache.keys())) {
      if (geometryCache.size <= GEOMETRY_CACHE_LIMIT) {
        break;
      }
      if (inUse.has(key)) {
        continue;
      }
      const entry = geometryCache.get(key);
      geometryCache.delete(key);
      if (entry.frontBack) {
        entry.frontBack.dispose();
      }
      if (entry.side) {
        entry.side.dispose();
      }
    }
  };
  const trimMaterialCache = (cache) => {
    if (cache.size <= MATERIAL_CACHE_LIMIT) {
      return;
    }
    const inUse = collectMaterialsInUse();
    for (const key of Array.from(cache.keys())) {
      if (cache.size <= MATERIAL_CACHE_LIMIT) {
        break;
      }
      const material = cache.get(key);
      if (!material || inUse.has(material.uuid)) {
        continue;
      }
      cache.delete(key);
      material.dispose();
    }
  };
  const trimMaskCache = () => {
    for (const key of Array.from(maskCache.keys())) {
      if (maskCache.size <= MASK_CACHE_LIMIT) {
        break;
      }
      maskCache.delete(key);
    }
