    for (let index = 0; index < alpha.length; index++) {
      const rgbaIndex = index * 4;
      alpha[index] = rgba[rgbaIndex + 3];
      colors[index * 3] = rgba[rgbaIndex] / 255;
      colors[index * 3 + 1] = rgba[rgbaIndex + 1] / 255;
      colors[index * 3 + 2] = rgba[rgbaIndex + 2] / 255;
