    return frontBack;
  };
  const makeEmptySideGeometry = () => {
    const side = new THREE.BufferGeometry();
    side.setAttribute("position", new THREE.BufferAttribute(new Float32Array(0), 3));
    side.setAttribute("normal", new THREE.BufferAttribute(new Float32Array(0), 3));
    side.setAttribute("color", new THREE.BufferAttribute(new Float32Array(0), 3));
    side.setIndex(new THREE.BufferAttribute(new Uint32Array(0), 1));
    side.boundingSphere = new THREE.Sphere(new THREE.Vector3(0, 0, 0), 0);
