    let entry = geometryCache.get(key);
    if (entry) {
      return entry;
    }
    entry = {
      frontBack: makeFrontBackGeometry(width, height, depth),
      side: makeEmptySideGeometry(),
      triangleCount: 4,
      vertexCount: 8,
      generationTimeMs: 0,
      width,
      height
