    trimGeometryCache();
    return entry;
  };
  const getOrBuildGeometry = (imageName, image, alphaThreshold, depth) => {
    const key = imageName + "|" + alphaThreshold + "|" + depth;
    let entry = geometryCache.get(key);
    if (entry) {
      return entry;
    }
    const startTime = performance.now();
    const mask = getAlphaData(imageName, image);
    const width = mask.width;
    const height = mask.height;
    const alpha = mask.alpha;
    const colors = mask.colors;
    const threshold = Math.max(1, alphaThreshold);
    const isSolid = (x, y) => x >= 0 && y >= 0 && x < width && y < height && alpha[y * width + x] >= threshold;
    const D = Math.max(1, depth);
    const sideInset = 0;
    const frontBack = makeFrontBackGeometry(width, height, depth);
    const positions = [];
    const normals = [];
    const wallColors = [];
    const indices = [];
    let wallVertexCount = 0;
    const pushWall = (x0, y0, x1, y1, nx, ny, colorX, colorY) => {
      const insetX = -nx * sideInset;
      const insetY = -ny * sideInset;
      positions.push(x0 + insetX, y0 + insetY, 0, x1 + insetX, y1 + insetY, 0, x1 + insetX, y1 + insetY, D, x0 + insetX, y0 + insetY, D);
      for (let corner = 0; corner < 4; corner++) {
        normals.push(nx, ny, 0);
      }
      const colorIndex = (colorY * width + colorX) * 3;
      const r = colors[colorIndex];
      const g = colors[colorIndex + 1];
      const b = colors[colorIndex + 2];
      for (let corner = 0; corner < 4; corner++) {
        wallColors.push(r, g, b);
      }
      indices.push(wallVertexCount, wallVertexCount + 1, wallVertexCount + 2, wallVertexCount, wallVertexCount + 2, wallVertexCount + 3);
      wallVertexCount += 4;
    };
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        if (!isSolid(x, y)) {
          continue;
        }
        if (!isSolid(x - 1, y)) {
          pushWall(x, y + 1, x, y, -1, 0, x, y);
        }
        if (!isSolid(x + 1, y)) {
          pushWall(x + 1, y, x + 1, y + 1, 1, 0, x, y);
        }
        if (!isSolid(x, y - 1)) {
          pushWall(x, y, x + 1, y, 0, -1, x, y);
        }
        if (!isSolid(x, y + 1)) {
          pushWall(x + 1, y + 1, x, y + 1, 0, 1, x, y);
