    const side = new THREE.BufferGeometry();
    side.setAttribute("position", new THREE.BufferAttribute(new Float32Array(positions), 3));
    side.setAttribute("normal", new THREE.BufferAttribute(new Float32Array(normals), 3));
    side.setAttribute("color", new THREE.BufferAttribute(new Float32Array(wallColors), 3));
    side.setIndex(new THREE.BufferAttribute(new Uint32Array(indices), 1));
    if (positions.length === 0) {
      side.boundingSphere = new THREE.Sphere(new THREE.Vector3(0, 0, 0), 0);
      side.boundingBox = new THREE.Box3(new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 0, 0));
    }
    entry = {
      frontBack,
      side,
      triangleCount: 4 + indices.length / 3,
      vertexCount: 8 + wallVertexCount,
      generationTimeMs: performance.now() - startTime,
      width,
      height
