    const inUse = collectGeometriesInUse();
    for (const key of Array.from(geometryCache.keys())) {
      if (key.indexOf(prefix) !== 0) {
        continue;
      }
      const entry = geometryCache.get(key);
      geometryCache.delete(key);
      if (inUse.has(key)) {
        continue;
      }
      if (entry.frontBack) {
        entry.frontBack.dispose();
      }
      if (entry.side) {
        entry.side.dispose();
      }
    }
  };
  const parseColor = (colorString) => {
    const color = new THREE.Color();
    const text = String(colorString);
    if (text.indexOf(";") === -1) {
      color.set(text);
      return color;
    }
    const parts = text.split(";");
    const red = Math.min(255, Math.max(0, Number(parts[0]) || 0));
    const green = Math.min(255, Math.max(0, Number(parts[1]) || 0));
    const blue = Math.min(255, Math.max(0, Number(parts[2]) || 0));
