    const color = parseColor(colorString);
    if (typeof color.getRGB === "function") {
      color.getRGB(tempColorChannels, THREE.SRGBColorSpace);
    } else {
      tempColorChannels.r = color.r;
      tempColorChannels.g = color.g;
      tempColorChannels.b = color.b;
    }
    const channel = (value) => Math.min(255, Math.max(0, Math.round(Number(value) * 255) || 0));
